B.asq = ASQ.map(function (r, i) {
  return {id: "asq" + String(i + 1).padStart(3, "0"), q: r[0], a: r[1], alt: r.slice(2)};
});
B.di = [
{id:"di01", kind:"bar", title:"Average weekly study hours by year of university", unit:"hours", labels:["Year 1","Year 2","Year 3","Year 4"], series:[{name:"Humanities",values:[14,16,19,22]},{name:"Sciences",values:[18,21,23,25]}],
 model:"The bar chart compares the average weekly study hours of humanities and science students across four years of university. Overall, study time increases in both fields, and science students study longer in every year. Humanities students rose from 14 hours in Year 1 to 22 in Year 4, while science students went from 18 to 25. The gap was widest in Year 1, at four hours, and narrowed to three hours by Year 4. In conclusion, workload grows steadily as students progress.",
 points:["Both groups study more each year","Science is higher in every year","The gap narrows from 4 to 3 hours"], vocab:["increased steadily","rose from ... to ...","remained higher than","the gap narrowed"],
 ar:"يوضح الرسم أن ساعات الدراسة الأسبوعية تزداد في كل سنة جامعية لدى طلاب الإنسانيات والعلوم، وطلاب العلوم يدرسون أكثر في كل سنة، لكن الفارق يتقلص من 4 ساعات إلى 3."},
{id:"di02", kind:"bar", title:"Households with internet access by region", unit:"%", labels:["North","South","East","West","Central"], series:[{name:"2010",values:[50,35,52,60,41]},{name:"2020",values:[89,78,91,94,82]}],
 model:"The bar chart illustrates the proportion of households with internet access in five regions in 2010 and 2020. Overall, access rose dramatically everywhere, and the West remained the most connected region. In 2010 the West led with 60 per cent, whereas the South trailed at 35 per cent. By 2020, every region exceeded 75 per cent, with the West reaching 94 per cent. The South showed the largest increase, climbing by 43 points to 78 per cent.",
 points:["All regions grew sharply","West highest in both years","South had the biggest rise (+43)"], vocab:["rose dramatically","climbed by","led with","trailed at","exceeded"],
 ar:"ارتفعت نسبة المنازل المتصلة بالإنترنت في جميع المناطق بين 2010 و2020؛ الغرب الأعلى في السنتين، والجنوب سجل أكبر زيادة (43 نقطة)."},
{id:"di03", kind:"bar", title:"Average monthly rainfall in a coastal city", unit:"mm", labels:["Jan","Mar","May","Jul","Sep","Nov"], series:[{name:"Rainfall",values:[78,64,41,12,29,85]}],
 model:"The bar chart shows average rainfall in a coastal city in six selected months. Overall, rainfall is highest at the start and end of the year and lowest in mid-summer. November was the wettest month at 85 millimetres, followed by January at 78. After falling steadily to a low of only 12 millimetres in July, rainfall recovered to 29 in September. March and May recorded 64 and 41 millimetres respectively.",
 points:["Wettest month is November (85 mm)","Driest month is July (12 mm)","Steady fall then recovery"], vocab:["peaked at","fell to a low of","recovered to","the wettest month","followed by"],
 ar:"الأمطار تبلغ ذروتها في نوفمبر (85 ملم) وتنخفض إلى أدنى مستوى في يوليو (12 ملم) ثم تعود للارتفاع في سبتمبر."},
{id:"di04", kind:"bar", title:"Factors students consider when choosing a university", unit:"%", labels:["Reputation","Course range","Cost","Location","Friends"], series:[{name:"Students citing factor",values:[62,48,41,35,17]}],
 model:"The bar chart presents the percentage of students who mentioned five factors when choosing a university. Overall, academic reputation was the most important consideration, while the influence of friends was minimal. Reputation was cited by 62 per cent of students, well ahead of course range at 48 per cent. Cost and location followed with 41 and 35 per cent respectively. Only 17 per cent said that friends affected their decision.",
 points:["Reputation ranks first (62%)","Cost and location in the middle","Friends matter least (17%)"], vocab:["was cited by","well ahead of","accounted for","the least influential","followed by"],
 ar:"السمعة الأكاديمية هي العامل الأهم (62%) تليها تنوع المقررات والتكلفة والموقع، بينما تأثير الأصدقاء ضعيف (17%)."},
{id:"di05", kind:"bar", title:"Average daily commuting time by transport", unit:"minutes", labels:["Walking","Cycling","Bus","Train","Car"], series:[{name:"Minutes per day",values:[18,25,42,55,36]}],
 model:"The bar chart compares the average daily commuting time using five means of transport. Overall, public transport takes considerably longer than active travel. Train commuters spend the longest, at 55 minutes, followed by bus users with 42 minutes. Car drivers take 36 minutes, which is less than either public option. Walking is the quickest at only 18 minutes, while cyclists need 25 minutes. Thus, commuting time differs greatly according to the mode chosen.",
 points:["Train is the longest (55 min)","Walking is the shortest (18 min)","Car sits in the middle (36 min)"], vocab:["the longest","considerably longer","less than","differs greatly","the quickest"],
 ar:"القطار هو الأطول زمنًا (55 دقيقة) والمشي الأقصر (18 دقيقة)، والسيارة في المنتصف (36 دقيقة)."},
{id:"di06", kind:"bar", title:"Electricity generation by source in two countries", unit:"TWh", labels:["Coal","Gas","Nuclear","Wind","Solar"], series:[{name:"Country A",values:[120,95,60,30,15]},{name:"Country B",values:[40,70,110,55,25]}],
 model:"The bar chart compares electricity generation from five sources in two countries. Overall, Country A depends mainly on fossil fuels, whereas Country B relies more on nuclear and renewable power. Country A produced 120 terawatt-hours from coal, three times more than Country B's 40. In contrast, Country B generated 110 from nuclear energy, nearly double Country A's 60. Renewable sources were small in both, although Country B led in wind and solar.",
 points:["A relies on coal and gas","B relies on nuclear","B leads in wind and solar"], vocab:["depends mainly on","in contrast","three times more than","nearly double","relies on"],
 ar:"الدولة A تعتمد على الفحم والغاز، والدولة B على الطاقة النووية والمتجددة، ومصادر الرياح والشمس أعلى في B."},
{id:"di07", kind:"bar", title:"Library books borrowed by faculty, per term", unit:"thousands", labels:["Arts","Law","Science","Business","Engineering"], series:[{name:"Term 1",values:[34,22,28,30,19]},{name:"Term 2",values:[38,25,24,33,21]}],
 model:"The bar chart shows how many books, in thousands, five faculties borrowed from the library in two terms. Overall, borrowing increased in most faculties, with science as the only exception. Arts students borrowed the most in both terms, rising from 34 to 38 thousand. Business and law also grew slightly. By contrast, science fell from 28 to 24 thousand. Engineering remained the lowest borrower, with 19 thousand in Term 1 and 21 thousand in Term 2.",
 points:["Most faculties borrowed more","Science is the only decline","Arts highest, engineering lowest"], vocab:["with the exception of","grew slightly","by contrast","remained the lowest","the only decline"],
 ar:"الاستعارة ارتفعت في معظم الكليات باستثناء العلوم التي انخفضت، والآداب الأعلى والهندسة الأدنى في الفصلين."},
{id:"di08", kind:"bar", title:"Average nightly sleep of teenagers by age", unit:"hours", labels:["13","14","15","16","17"], series:[{name:"Hours of sleep",values:[9.1,8.6,8.1,7.6,7.2]}],
 model:"The bar chart displays the average amount of sleep teenagers get each night between the ages of 13 and 17. Overall, sleep declines consistently as teenagers grow older. Thirteen-year-olds sleep for 9.1 hours, the highest figure, whereas seventeen-year-olds manage only 7.2 hours. The decrease is regular, with roughly half an hour lost each year. In total, sleep falls by 1.9 hours across the five ages, suggesting that older teenagers are more likely to be tired.",
 points:["Sleep falls with every year of age","From 9.1 to 7.2 hours","About 30 minutes lost per year"], vocab:["declines consistently","dropped by","a regular decrease","roughly half an hour","manage only"],
 ar:"ينخفض متوسط النوم باستمرار مع تقدم العمر من 9.1 ساعات عند 13 سنة إلى 7.2 عند 17 سنة، أي نحو نصف ساعة في كل عام."},
{id:"di09", kind:"line", title:"Average monthly temperature in two cities", unit:"°C", labels:["Jan","Mar","May","Jul","Sep","Nov"], series:[{name:"City A",values:[14,18,27,34,30,20]},{name:"City B",values:[2,6,13,20,14,5]}],
 model:"The line graph compares average temperatures in two cities over six months. Overall, both cities follow the same seasonal pattern, peaking in July, but City A is much warmer throughout. City A rose from 14 degrees in January to a peak of 34 in July, then fell to 20 in November. City B climbed from 2 to 20 degrees before dropping to 5. The difference between them was 12 degrees in January and 14 in July.",
 points:["Same pattern, peak in July","City A always warmer","Gap is 12 to 14 degrees"], vocab:["peaked at","followed the same pattern","climbed from ... to ...","fell back to","remained warmer"],
 ar:"المدينتان تتبعان النمط الموسمي نفسه بذروة في يوليو، لكن المدينة A أدفأ دائمًا بفارق 12 إلى 14 درجة."},
{id:"di10", kind:"line", title:"Smartphone ownership by age group", unit:"%", labels:["2014","2016","2018","2020","2022"], series:[{name:"Under 30",values:[62,75,85,92,96]},{name:"Over 60",values:[14,25,38,52,66]}],
 model:"The line graph shows the percentage of people who owned a smartphone in two age groups between 2014 and 2022. Overall, ownership grew in both groups, but younger people remained far ahead. The under-30s increased from 62 to 96 per cent, levelling off near the end. Ownership among over-60s rose much faster, from only 14 to 66 per cent. As a result, the gap narrowed from 48 percentage points to 30.",
 points:["Both groups rose","Under 30 near saturation (96%)","Gap narrowed from 48 to 30"], vocab:["levelled off","rose steadily","far ahead of","narrowed","a sharp increase"],
 ar:"زادت ملكية الهواتف الذكية في الفئتين؛ الشباب وصلوا إلى 96% تقريبًا بينما ارتفعت نسبة كبار السن من 14% إلى 66% وتقلص الفارق."},
{id:"di11", kind:"line", title:"Annual visitors to a national park", unit:"thousands", labels:["2015","2017","2019","2021","2023"], series:[{name:"Visitors",values:[220,260,310,150,340]}],
 model:"The line graph illustrates the number of visitors to a national park over eight years. Overall, attendance increased, apart from a sharp decline in 2021. Numbers climbed steadily from 220 thousand in 2015 to 310 thousand in 2019. They then dropped dramatically to 150 thousand in 2021, the lowest figure. However, a strong recovery followed, and visitors reached a record 340 thousand in 2023. This suggests that the park has regained its popularity after a difficult period.",
 points:["Steady growth until 2019","Sharp fall to 150k in 2021","Record high in 2023 (340k)"], vocab:["dropped dramatically","a strong recovery","reached a record","the lowest figure","apart from"],
 ar:"زاد عدد زوار المتنزه حتى 2019 ثم انخفض بشدة في 2021 إلى 150 ألفًا، وبعدها تعافى ليبلغ رقمًا قياسيًا 340 ألفًا في 2023."},
{id:"di12", kind:"line", title:"Price of petrol per litre", unit:"$", labels:["2016","2017","2018","2019","2020","2021"], series:[{name:"Price",values:[1.05,1.12,1.30,1.18,1.45,1.82]}],
 model:"The line graph shows how the price of petrol changed per litre between 2016 and 2021. Overall, prices rose significantly, despite one temporary fall. The price started at 1.05 dollars and climbed to 1.30 in 2018. It then dipped to 1.18 in 2019 before rising again to 1.45 in 2020. The sharpest increase occurred in the final year, when the price reached 1.82 dollars, an overall rise of 77 cents.",
 points:["Overall upward trend","Temporary dip in 2019","Sharpest rise in 2021"], vocab:["rose significantly","dipped to","the sharpest increase","despite","an overall rise of"],
 ar:"ارتفع سعر البنزين بشكل عام من 1.05 إلى 1.82 دولار مع انخفاض مؤقت في 2019، وأكبر قفزة كانت في 2021."},
{id:"di13", kind:"line", title:"Online and on-campus course enrolment", unit:"%", labels:["2016","2018","2020","2022","2024"], series:[{name:"Online",values:[12,18,45,52,60]},{name:"On-campus",values:[88,82,55,48,40]}],
 model:"The line graph compares the share of students enrolled in online and on-campus courses from 2016 to 2024. Overall, online study grew considerably while campus attendance declined. Online enrolment increased from 12 to 60 per cent, with the steepest rise between 2018 and 2020. On-campus enrolment fell from 88 to 40 per cent. The two lines crossed between 2020 and 2022, when online courses became the more popular option.",
 points:["Online up from 12% to 60%","On-campus down from 88% to 40%","Lines cross between 2020 and 2022"], vocab:["the steepest rise","overtook","crossed","declined sharply","the more popular option"],
 ar:"ارتفعت نسبة الدراسة عبر الإنترنت من 12% إلى 60% وانخفضت الدراسة بالحرم من 88% إلى 40%، وتقاطع الخطان بين 2020 و2022."},
{id:"di14", kind:"line", title:"Unemployment rate in two countries", unit:"%", labels:["2018","2019","2020","2021","2022"], series:[{name:"Country X",values:[8.5,7.9,7.2,6.1,5.4]},{name:"Country Y",values:[4.2,4.4,5.8,5.1,4.6]}],
 model:"The line graph shows unemployment rates in two countries from 2018 to 2022. Overall, Country X had higher unemployment throughout, although its rate fell continuously. It declined from 8.5 to 5.4 per cent. By contrast, Country Y fluctuated, rising from 4.2 to a peak of 5.8 per cent in 2020 before falling back to 4.6. Consequently, the difference between the two countries narrowed from 4.3 points to 0.8.",
 points:["X falls every year","Y peaks in 2020 (5.8%)","The gap narrows to 0.8 points"], vocab:["fluctuated","fell continuously","peaked at","fell back to","the difference narrowed"],
 ar:"بطالة الدولة X أعلى طوال الفترة لكنها تنخفض باستمرار، أما Y فتذبذبت وبلغت ذروتها 5.8% في 2020، ويضيق الفارق بين الدولتين."},
{id:"di15", kind:"pie", title:"How a household spends its monthly budget", unit:"%", labels:["Housing","Food","Transport","Education","Leisure","Savings"], series:[{name:"Share of budget",values:[35,20,15,12,10,8]}],
 model:"The pie chart shows how a typical household divides its monthly budget among six categories. Overall, housing takes the largest share, while savings account for the smallest. Housing represents 35 per cent, well above food at 20 per cent. Transport comes next with 15 per cent, followed by education at 12. Leisure makes up 10 per cent. Only 8 per cent is saved, so essential costs dominate the family's spending.",
 points:["Housing largest at 35%","Food second at 20%","Savings smallest at 8%"], vocab:["accounts for","makes up","the largest share","the smallest proportion","followed by"],
 ar:"السكن يستحوذ على أكبر حصة (35%) ثم الطعام (20%)، بينما الادخار أصغر بند (8%)."},
{id:"di16", kind:"pie", title:"Sources of a country's energy supply", unit:"%", labels:["Oil","Gas","Coal","Renewables","Nuclear"], series:[{name:"Share of energy",values:[32,26,18,16,8]}],
 model:"The pie chart illustrates the proportion of energy supplied by five sources in one country. Overall, fossil fuels dominate, whereas nuclear power is marginal. Oil is the leading source at 32 per cent, followed by gas with 26 per cent. Coal supplies 18 per cent. Renewable energy provides 16 per cent, which is double the contribution of nuclear power at only 8 per cent. Together, oil, gas and coal supply three quarters of energy.",
 points:["Oil leads (32%)","Fossil fuels = 76% together","Nuclear smallest (8%)"], vocab:["the leading source","supplies","dominate","marginal","double the contribution"],
 ar:"النفط أكبر مصدر (32%) ثم الغاز (26%)، والوقود الأحفوري مجتمعًا يمثل نحو ثلاثة أرباع الطاقة بينما النووي الأقل (8%)."},
{id:"di17", kind:"pie", title:"What graduates do six months after finishing", unit:"%", labels:["Private sector","Public sector","Further study","Self-employed","Unemployed"], series:[{name:"Share of graduates",values:[46,22,17,9,6]}],
 model:"The pie chart shows the activities of graduates six months after completing their degrees. Overall, most graduates are in work, and very few are unemployed. Almost half, or 46 per cent, work in the private sector, while 22 per cent are employed by the public sector. A further 17 per cent continue studying. Nine per cent have become self-employed, and just 6 per cent have not found a job.",
 points:["46% work in private sector","Most graduates are employed","Only 6% unemployed"], vocab:["almost half","a further 17 per cent","just 6 per cent","are employed by","the majority"],
 ar:"نحو نصف الخريجين (46%) يعملون في القطاع الخاص، و22% في القطاع العام، و17% يواصلون الدراسة، و6% فقط بلا عمل."},
{id:"di18", kind:"pie", title:"How students travel to campus", unit:"%", labels:["Bus","Walking","Car","Bicycle","Train"], series:[{name:"Share of students",values:[34,25,20,12,9]}],
 model:"The pie chart divides students according to how they travel to campus. Overall, the bus is the most common method, and the train is the least common. A third of students, 34 per cent, take the bus, while a quarter walk. Twenty per cent drive, and 12 per cent cycle. Only 9 per cent use the train. Interestingly, walking and cycling together account for more students than driving.",
 points:["Bus is most popular (34%)","A quarter walk","Train least used (9%)"], vocab:["the most common method","a quarter of","a third of","the least common","together account for"],
 ar:"الحافلة أكثر وسيلة شيوعًا (34%) ويمشي ربع الطلاب، والقطار الأقل استخدامًا (9%)، والمشي والدراجة معًا أكثر من السيارة."},
{id:"di19", kind:"pie", title:"Types of books borrowed from a public library", unit:"%", labels:["Fiction","Science","History","Languages","Other"], series:[{name:"Share of loans",values:[28,24,18,16,14]}],
 model:"The pie chart shows the types of books borrowed from a public library. Overall, the distribution is fairly even, with fiction slightly ahead. Fiction accounts for 28 per cent of loans, closely followed by science at 24 per cent. History books represent 18 per cent, and language books 16 per cent. The remaining 14 per cent covers other subjects. No category exceeds 30 per cent, indicating a varied range of reading interests.",
 points:["Fiction 28%, science 24%","Fairly even distribution","No category above 30%"], vocab:["fairly even","slightly ahead","closely followed by","the remaining","no category exceeds"],
 ar:"التوزيع متقارب؛ الروايات 28% والعلوم 24% والتاريخ 18% واللغات 16% وأخرى 14%، ولا تتجاوز أي فئة 30%."},
{id:"di20", kind:"table", title:"Four universities compared", unit:"", labels:["Northfield","Eastgate","Lakeside","Riverton"], series:[{name:"Students (thousands)",values:[24,15,31,9]},{name:"International students (%)",values:[18,25,12,30]},{name:"Graduate employment (%)",values:[88,91,84,93]}],
 model:"The table compares four universities in terms of size, international students and graduate employment. Overall, the smallest university performs best on two measures. Lakeside is the largest, with 31 thousand students, yet it has the lowest employment rate, at 84 per cent. Riverton has only 9 thousand students but the highest proportions of international students and employed graduates, at 30 and 93 per cent. Northfield and Eastgate fall in between.",
 points:["Lakeside biggest, Riverton smallest","Riverton best for international share and employment","Lakeside lowest employment (84%)"], vocab:["in terms of","yet","the highest proportion","fall in between","performs best"],
 ar:"جامعة ليكسايد الأكبر لكن توظيف خريجيها الأقل (84%)، وريفرتون الأصغر لكنها الأعلى في نسبة الطلاب الدوليين (30%) وتوظيف الخريجين (93%)."},
{id:"di21", kind:"table", title:"Average monthly rent in four cities", unit:"$", labels:["Aldton","Brenford","Carsmouth","Dunmere"], series:[{name:"Studio",values:[650,540,780,430]},{name:"One-bedroom",values:[820,700,990,560]},{name:"Shared room",values:[380,320,450,260]}],
 model:"The table gives the average monthly rent for three types of accommodation in four cities. Overall, Carsmouth is the most expensive city in every category, while Dunmere is the cheapest. A studio in Carsmouth costs 780 dollars, compared with just 430 in Dunmere. One-bedroom flats follow the same pattern, ranging from 560 to 990 dollars. Shared rooms are the most affordable option everywhere, costing between 260 and 450 dollars.",
 points:["Carsmouth most expensive","Dunmere cheapest","Shared rooms cheapest type"], vocab:["compared with","ranging from ... to ...","the most affordable","follow the same pattern","in every category"],
 ar:"كارسموث الأغلى في كل فئات السكن ودنمير الأرخص، والغرف المشتركة هي الخيار الأرخص في كل المدن."},
{id:"di22", kind:"table", title:"Weekly hours spent on activities by students", unit:"hours", labels:["Studying","Part-time work","Socialising","Sport"], series:[{name:"Year 1",values:[18,8,14,5]},{name:"Year 3",values:[24,12,9,3]}],
 model:"The table shows how many hours per week students spend on four activities in their first and third years. Overall, third-year students devote more time to study and work but less to leisure. Studying rises from 18 to 24 hours, and part-time work from 8 to 12. In contrast, socialising falls from 14 to 9 hours, and sport from 5 to 3. Studying is the largest commitment in both years.",
 points:["Study and work increase","Socialising and sport decrease","Studying biggest in both years"], vocab:["devote more time to","in contrast","falls from ... to ...","the largest commitment","in both years"],
 ar:"طلاب السنة الثالثة يخصصون وقتًا أكبر للدراسة والعمل وأقل للترفيه والرياضة، والدراسة هي الأكبر في السنتين."},
{id:"di23", kind:"process", title:"How drinking water is purified", unit:"",
 steps:["Step 1: Water is collected from a river or reservoir.","Step 2: It passes through screens that remove leaves and large debris.","Step 3: Chemicals are added so tiny particles stick together.","Step 4: The heavy clumps settle at the bottom of a large tank.","Step 5: The clearer water is filtered through layers of sand and gravel.","Step 6: Chlorine is added to kill bacteria before the water enters the supply pipes."],
 model:"The diagram illustrates how drinking water is purified in six stages. Overall, the process moves from collecting raw water to disinfecting it. First, water is taken from a river or reservoir. Next, screens remove large debris. After that, chemicals make small particles stick together, and these clumps settle in a tank. The water is then filtered through sand and gravel. Finally, chlorine is added to kill bacteria before distribution.",
 points:["Six stages from river to pipes","Settling and filtering remove solids","Chlorine is the final step"], vocab:["First","Next","After that","is then filtered","Finally","prior to distribution"],
 ar:"تتم تنقية مياه الشرب في ست مراحل: جمع المياه، إزالة الشوائب الكبيرة، إضافة مواد كيميائية، الترسيب، الترشيح بالرمل والحصى، ثم التعقيم بالكلور."},
{id:"di24", kind:"process", title:"How paper is recycled", unit:"",
 steps:["Step 1: Used paper is collected from homes and offices.","Step 2: It is sorted and the plastic and metal are removed.","Step 3: The paper is mixed with water and broken down into pulp.","Step 4: The pulp is cleaned and the ink is washed out.","Step 5: It is pressed into thin sheets and dried with heated rollers.","Step 6: The new paper is cut and rolled for delivery to customers."],
 model:"The diagram shows how used paper is turned into new paper in six steps. At the start, paper is collected from homes and offices and then sorted to remove plastic and metal. Next, it is mixed with water to form pulp, which is cleaned of ink. The pulp is then pressed into sheets and dried by heated rollers. In the final stage, the finished paper is cut and rolled for delivery.",
 points:["Collection and sorting come first","Pulping and de-inking in the middle","Pressing, drying and cutting at the end"], vocab:["is collected","is sorted","is mixed with water","is pressed into","in the final stage"],
 ar:"يحوَّل الورق المستعمل إلى ورق جديد في ست خطوات: الجمع، الفرز، صنع اللب مع الماء، تنظيفه من الحبر، الكبس والتجفيف، ثم القص والتغليف."}
];
B.rl = [
{id:"rl01", title:"Why we forget", transcript:"Today I would like to talk about forgetting. Many people assume that forgetting is a failure of the brain, but psychologists increasingly see it as a useful feature. If we remembered every detail of every day, important information would be buried under trivial facts. The brain therefore filters experiences, keeping what seems relevant and letting the rest fade. A famous experiment in the nineteenth century showed that most forgetting happens within the first hour after learning. This is why reviewing material soon after a lecture, and again after a few days, makes such a difference.",
 keywords:["forgetting","useful filter","first hour","review"], notes:"forgetting = feature not bug | brain filters | most loss in 1st hr | review soon + later",
 model:"The lecture explains that forgetting is not a failure but a useful filter, because the brain keeps relevant information and discards trivial details. Most forgetting happens in the first hour after learning, so students should review their notes soon after a lecture and again a few days later.",
 ar:"المحاضرة تشرح أن النسيان ليس عيبًا بل آلية مفيدة لتصفية المعلومات، وأن أغلب النسيان يحدث في الساعة الأولى لذا تجب المراجعة مبكرًا ثم بعد أيام."},
{id:"rl02", title:"Urban beekeeping", transcript:"In recent years, beekeeping has become surprisingly popular in major cities. Rooftop hives are now found on offices, hotels, and even universities. Interestingly, urban bees often produce more honey than their rural counterparts. One reason is that city gardens and parks offer a longer flowering season, with a wide variety of plants. Another is that cities usually use fewer agricultural pesticides. However, ecologists caution that too many hives can compete with wild pollinators for limited food. They suggest that urban beekeepers plant more flowers and avoid overcrowding the same area.",
 keywords:["rooftop hives","more honey","pesticides","wild pollinators"], notes:"city bees > rural honey | why: long flower season, less pesticide | risk: compete w/ wild pollinators | fix: plant flowers",
 model:"The speaker describes the growth of urban beekeeping, noting that city bees often make more honey because of long flowering seasons and fewer pesticides. However, too many hives may compete with wild pollinators for food, so ecologists recommend planting more flowers and avoiding overcrowding. This balance protects both honey production and local biodiversity.",
 ar:"تتحدث المحاضرة عن تربية النحل في المدن حيث ينتج نحل المدن عسلًا أكثر، لكن كثرة الخلايا قد تنافس الملقّحات البرية لذا يُنصح بزراعة المزيد من الأزهار."},
{id:"rl03", title:"The origins of money", transcript:"Before money existed, people traded goods directly, a system known as barter. Barter has an obvious weakness: it requires a double coincidence of wants. A farmer with spare wheat must find a potter who happens to need wheat, and who also has pots to offer. To solve this problem, societies began to use commodities such as shells, salt, or metal as a common measure of value. Eventually, coins were produced with a guaranteed weight, and later paper notes replaced them. Today, much of our money exists only as digital records.",
 keywords:["barter","double coincidence","commodities","coins","digital"], notes:"barter -> problem: need match | commodity money (shells, salt, metal) | coins | paper | digital now",
 model:"The lecture traces the development of money. Barter was inefficient because both traders had to want what the other offered. Societies therefore adopted commodities like shells or metal, then standard coins and paper notes, and today most money exists as digital records. This long process shows how trade needs shaped modern finance.",
 ar:"تتبع المحاضرة تطور النقود: المقايضة كانت صعبة لحاجتها لتوافق رغبتين، ثم ظهرت سلع كوسيط، فالعملات المعدنية والورقية، واليوم معظم المال رقمي."},
{id:"rl04", title:"Coral reefs under pressure", transcript:"Coral reefs cover less than one percent of the ocean floor, yet they support about a quarter of all marine species. Corals are tiny animals that live in partnership with algae, which give them food and colour. When the water becomes too warm, the corals expel the algae, turn white, and may die. This process is called bleaching. Scientists are now experimenting with heat-resistant corals and with growing new fragments in nurseries. Nevertheless, they stress that protecting reefs ultimately requires reducing greenhouse gas emissions.",
 keywords:["reefs","algae","bleaching","heat-resistant","emissions"], notes:"reefs <1% floor, 25% species | coral + algae | warm water -> bleaching | fixes: tough coral, nurseries | real fix = cut emissions",
 model:"The lecture explains that coral reefs, though small in area, support a quarter of marine species. Warm water causes corals to expel their algae and bleach. Researchers are testing heat-resistant corals and nurseries, but they emphasise that reducing greenhouse gas emissions is the real solution.",
 ar:"الشعاب المرجانية تغطي مساحة صغيرة لكنها تدعم ربع الكائنات البحرية، وارتفاع حرارة الماء يسبب ابيضاضها، والحل الحقيقي هو خفض الانبعاثات."},
{id:"rl05", title:"The psychology of colour", transcript:"Does colour influence how we feel and behave? Marketing researchers certainly believe so. Blue is often used by banks because it is associated with trust and calm, while red suggests urgency and is common in sales signs. However, psychologists warn against simple rules. The meaning of a colour depends heavily on culture, personal experience, and context. For example, white represents weddings in some countries but mourning in others. Studies show that colour does have an effect, but it is usually modest and works best when it matches the message of the product.",
 keywords:["colour","trust","urgency","culture","context"], notes:"blue = trust (banks) | red = urgency (sales) | BUT culture + context matter | e.g. white wedding vs mourning | effect modest",
 model:"The speaker discusses how colour affects emotions and marketing. Blue suggests trust and red suggests urgency, but meanings vary across cultures and contexts, as white shows. Research indicates that colour has a modest effect, which is strongest when it fits the product's message. Marketers should therefore consider their audience carefully.",
 ar:"المحاضرة تناقش تأثير الألوان؛ الأزرق يوحي بالثقة والأحمر بالإلحاح، لكن المعنى يختلف حسب الثقافة والسياق، والتأثير عمومًا متوسط."},
{id:"rl06", title:"Sleep and teenagers", transcript:"Teenagers are often described as lazy because they wake late and stay up at night, but biology offers a different explanation. During adolescence, the body clock shifts, so melatonin, the hormone that makes us sleepy, is released later in the evening. As a result, many teenagers cannot fall asleep before eleven o'clock, yet school often starts at eight. Some districts have experimented with later start times and reported improved attendance, better grades, and fewer car accidents. The evidence suggests that adjusting school hours is a simple and effective reform.",
 keywords:["body clock","melatonin","later start times","grades"], notes:"teens not lazy | body clock shifts, melatonin late | school starts 8 | later start -> attendance up, grades up, fewer crashes",
 model:"The lecture argues that teenagers are not lazy; their body clocks shift so they feel sleepy later at night. Schools that started later reported better attendance, higher grades, and fewer car accidents, suggesting that changing school hours is a simple and effective reform. Therefore, this could improve students' health and safety.",
 ar:"المراهقون ليسوا كسالى بل تتأخر ساعتهم البيولوجية، وتأخير بدء الدراسة حسّن الحضور والدرجات وقلل الحوادث."},
{id:"rl07", title:"Glaciers and sea level", transcript:"Glaciers are rivers of ice that move slowly downhill under their own weight. They store about two thirds of the world's fresh water. As global temperatures rise, many glaciers are retreating, and the meltwater flows into the oceans, raising sea level. Coastal cities and low-lying islands are particularly vulnerable. Moreover, communities that depend on glacial rivers for drinking water and irrigation may face shortages once the ice has gone. Researchers monitor glaciers using satellites and field measurements to predict how quickly these changes will occur.",
 keywords:["glaciers","fresh water","retreat","sea level","shortages"], notes:"glaciers = 2/3 fresh water | warming -> retreat | meltwater -> sea level up | coastal risk | later: water shortage | monitor via satellites",
 model:"The lecture explains that glaciers hold most of the world's fresh water but are retreating as temperatures rise. The meltwater raises sea levels, threatening coastal areas, and may eventually cause water shortages for communities that depend on glacial rivers. Scientists track the changes using satellites.",
 ar:"الأنهار الجليدية تخزن معظم المياه العذبة وهي تتراجع مع الاحترار، مما يرفع مستوى البحر ويهدد السواحل ثم يسبب نقص مياه للمجتمعات المعتمدة عليها."},
{id:"rl08", title:"What makes a good leader", transcript:"For decades, scholars have tried to identify the traits of effective leaders. Early theories focused on personal qualities such as confidence and charisma. More recent research, however, suggests that leadership depends on the situation. A leader who is excellent in a crisis may be less successful in a stable organisation. The best leaders appear to share one skill: they adapt their style to the needs of their team. They listen carefully, delegate tasks, and admit mistakes. Such behaviour builds trust, which in turn improves performance.",
 keywords:["leadership","situation","adapt","trust"], notes:"old view: traits | new view: situation matters | key skill = adapt | listen, delegate, admit errors -> trust -> performance",
 model:"The lecturer says early theories linked leadership to traits like charisma, but newer research shows it depends on context. The most effective leaders adapt their style to the team by listening, delegating, and admitting mistakes, which builds trust and therefore improves performance. Overall, flexibility matters more than any fixed personality.",
 ar:"النظريات القديمة ربطت القيادة بالصفات الشخصية، أما الحديثة فترى أنها تعتمد على الموقف، وأفضل القادة يتكيفون ويستمعون ويفوضون ويعترفون بأخطائهم فيبنون الثقة."},
{id:"rl09", title:"The printing revolution", transcript:"Before the fifteenth century, books in Europe were copied by hand, which made them rare and expensive. The introduction of movable type printing changed this dramatically. Within decades, presses had been established in hundreds of towns, and the price of books fell sharply. Literacy increased, and new ideas spread across borders far more quickly than before. Historians connect the printing press to the growth of science, the Reformation, and the development of national languages. In many ways, it was the first information revolution, comparable to the internet in our own time.",
 keywords:["movable type","cheaper books","literacy","ideas","information revolution"], notes:"before: hand copy = rare/costly | movable type -> presses everywhere, cheap books | literacy up, ideas spread | science, Reformation, languages | = 1st info revolution",
 model:"The lecture describes how printing with movable type replaced hand copying, making books cheaper and more common. Literacy rose and ideas travelled quickly, contributing to science, religious reform, and national languages. The speaker compares this first information revolution with the modern internet. Overall, printing changed society profoundly.",
 ar:"الطباعة بالحروف المتحركة جعلت الكتب أرخص وأوسع انتشارًا، ورفعت القراءة ونشرت الأفكار، وساهمت في العلم والإصلاح الديني، وتشبه ثورة الإنترنت."},
{id:"rl10", title:"Microplastics", transcript:"Microplastics are fragments of plastic smaller than five millimetres. Some are manufactured, such as the tiny beads once added to cosmetics. Others result from larger items breaking down in the environment. They have now been found in oceans, rivers, soil, and even drinking water. Marine animals mistake them for food, and the particles can move up the food chain. The health effects on humans are still unclear, which is why researchers call for more studies. In the meantime, reducing single-use plastic remains the most practical way to limit the problem.",
 keywords:["microplastics","five millimetres","food chain","unclear effects","single-use"], notes:"micro = <5 mm | sources: made + broken down | found everywhere | animals eat -> food chain | human effects unclear | cut single-use plastic",
 model:"The speaker defines microplastics as plastic fragments under five millimetres, either manufactured or created when larger items break down. They are widespread, enter the food chain, and have unclear effects on human health, so researchers urge further study while advising people to reduce single-use plastic.",
 ar:"الميكروبلاستيك قطع بلاستيكية أصغر من خمسة ملم منتشرة في كل مكان وتدخل السلسلة الغذائية، وأثرها على الإنسان غير واضح، ويُنصح بتقليل البلاستيك أحادي الاستخدام."},
{id:"rl11", title:"Learning styles: fact or myth?", transcript:"Many teachers believe that students learn best when instruction matches their preferred style, whether visual, auditory, or kinesthetic. The idea is popular and intuitive. Yet controlled experiments have repeatedly failed to show that matching teaching to style improves results. What does help is using multiple methods for everyone. For instance, combining diagrams with spoken explanation tends to strengthen understanding for all learners. Researchers therefore suggest that the learning styles theory is largely a myth, although students certainly have preferences. Good teaching depends more on the subject matter than on the learner's label.",
 keywords:["learning styles","myth","experiments","multiple methods"], notes:"belief: match style (V/A/K) | experiments: no gain | better = mix methods | e.g. diagram + speech | preferences real, theory myth",
 model:"The lecture challenges the popular belief that teaching should match visual, auditory, or kinesthetic styles. Experiments show no improvement from matching, while using several methods together, such as diagrams with speech, helps everyone. The speaker concludes that learning styles are largely a myth. Teachers should therefore focus on the subject itself.",
 ar:"المحاضرة تنفي فكرة أن مطابقة التدريس لنمط المتعلم تحسّن النتائج، وتؤكد أن الجمع بين عدة أساليب مفيد للجميع وأن نظرية أنماط التعلم أسطورة إلى حد كبير."},
{id:"rl12", title:"Volcanoes and climate", transcript:"Large volcanic eruptions can cool the planet for a year or two. When a volcano erupts violently, it releases sulphur dioxide high into the atmosphere, where it forms tiny droplets that reflect sunlight back into space. After the eruption of Mount Tambora in 1815, the following year became known as the year without a summer, with crop failures across the Northern Hemisphere. Today, scientists study such events to understand how the atmosphere responds. Some even propose imitating this effect artificially, although many experts consider the risks of such experiments too great.",
 keywords:["eruption","sulphur dioxide","reflect sunlight","Tambora","artificial cooling"], notes:"big eruption -> SO2 in atmosphere -> droplets reflect sun -> cooling 1-2 yrs | Tambora 1815: no summer, crops fail | idea: copy it artificially | risky",
 model:"The lecture explains that major eruptions release sulphur dioxide, which forms droplets that reflect sunlight and cool the Earth temporarily. The 1815 Tambora eruption caused a year without a summer. Some people suggest copying this artificially, but many experts think the risks are too high.",
 ar:"الانفجارات البركانية الكبيرة تطلق ثاني أكسيد الكبريت الذي يعكس ضوء الشمس ويبرد الأرض مؤقتًا، كما حدث بعد تامبورا 1815، ويرى كثيرون أن محاكاته صناعيًا خطرة."},
{id:"rl13", title:"Bilingual brains", transcript:"Research on bilingualism has produced some encouraging findings. People who use two languages regularly must constantly choose one and suppress the other, which exercises the brain's control system. As a result, bilinguals often perform better on tasks that require switching attention. Some studies also suggest that bilingualism may delay the symptoms of dementia by several years. Nevertheless, scientists are careful not to exaggerate. The cognitive advantages are small, and not every study has found them. The social and cultural benefits of speaking two languages are, in any case, beyond dispute.",
 keywords:["bilingual","control system","switching attention","dementia","benefits"], notes:"2 langs -> choose/suppress = brain exercise | better at switching | may delay dementia | gains small, not always found | social/cultural benefits sure",
 model:"The speaker reports that bilinguals constantly manage two languages, which trains attention control and may delay dementia. However, the cognitive benefits are small and not found in every study, so scientists avoid exaggeration. The social and cultural advantages of bilingualism are undisputed. Overall, the evidence is encouraging but not conclusive.",
 ar:"ثنائيو اللغة يدربون التحكم الذهني ويتحسن تبديل الانتباه وقد يتأخر الخرف، لكن الفوائد المعرفية صغيرة وغير مؤكدة دائمًا بينما الفوائد الاجتماعية والثقافية مؤكدة."},
{id:"rl14", title:"The gig economy", transcript:"The gig economy refers to a labour market in which people earn money through short-term tasks arranged via digital platforms, such as delivery or freelance design. Supporters praise the flexibility, since workers choose when and how much to work. Critics point out that gig workers usually lack paid leave, health insurance, and job security. Governments are now debating whether these workers should be classified as employees. The outcome will influence not only the platforms but also the millions of people who rely on this form of income to make ends meet.",
 keywords:["gig economy","platforms","flexibility","job security","employees"], notes:"gig = short tasks via apps | pro: flexible | con: no leave, insurance, security | debate: employee status? | affects millions",
 model:"The lecture introduces the gig economy, where people do short-term work through digital platforms. It offers flexibility, but workers often lack leave, insurance, and security. Governments are debating whether such workers should count as employees, a decision affecting millions of people and the platform companies.",
 ar:"اقتصاد المهام القصيرة يتيح مرونة للعاملين عبر المنصات الرقمية لكنه يفتقر للإجازات والتأمين والأمان الوظيفي، والحكومات تناقش اعتبارهم موظفين."},
{id:"rl15", title:"Why the sky is blue", transcript:"The sky appears blue because of the way sunlight interacts with the atmosphere. Sunlight looks white but is actually a mixture of all colours. When it enters the atmosphere, it collides with gas molecules, which scatter short wavelengths, such as blue, much more strongly than long wavelengths, such as red. Our eyes therefore receive scattered blue light from every direction. At sunrise and sunset, light travels through more air, so most of the blue is scattered away and the sky turns red and orange. This phenomenon is known as Rayleigh scattering.",
 keywords:["sunlight","scattering","blue","wavelength","sunset"], notes:"white light = all colours | air molecules scatter blue most | blue from all directions = blue sky | sunset: longer path -> red/orange | Rayleigh scattering",
 model:"The lecture explains that sunlight contains all colours, and atmospheric gases scatter blue light more strongly than red, so we see a blue sky. At sunrise and sunset, light passes through more air, scattering the blue away and leaving red and orange. This is called Rayleigh scattering.",
 ar:"السماء زرقاء لأن جزيئات الغلاف الجوي تشتت الضوء الأزرق أكثر من الأحمر، وعند الشروق والغروب يقطع الضوء مسافة أطول فتظهر ألوان حمراء وبرتقالية."},
{id:"rl16", title:"Public libraries in the digital age", transcript:"Some people predicted that the internet would make public libraries obsolete. In fact, the opposite has happened in many cities. Visits have remained strong because libraries have changed their role. Besides lending books, they now provide free computer access, classes for job seekers, and quiet places to study. For people without internet at home, a library may be the only connection to online services such as government forms. Library managers argue that these spaces strengthen communities, and they are asking councils to protect their budgets.",
 keywords:["libraries","obsolete","free access","community","budgets"], notes:"prediction: libraries die | reality: visits steady | new roles: computers, job classes, study space | only internet for some | community value -> protect budgets",
 model:"The speaker says libraries have not become obsolete despite the internet. They adapted by offering computer access, job-seeker classes, and study space, which is vital for people without home internet. Managers claim libraries strengthen communities and ask councils to protect their funding. Overall, libraries remain important public institutions.",
 ar:"المكتبات العامة لم تصبح بلا فائدة بل طورت دورها بتوفير الحواسيب ودروس الباحثين عن عمل وأماكن الدراسة، ويطالب مديروها بحماية ميزانياتها."},
{id:"rl17", title:"Antibiotic resistance", transcript:"Antibiotics transformed medicine in the twentieth century, turning once-deadly infections into treatable conditions. Today, however, bacteria are evolving resistance faster than new drugs are being developed. Every time antibiotics are used, a few bacteria may survive and multiply. Overuse, such as prescribing antibiotics for viral illnesses, speeds up this process. The consequences could include routine surgery becoming dangerous again. Health authorities therefore urge patients to complete their prescribed courses, doctors to prescribe carefully, and governments to fund research into alternative treatments.",
 keywords:["antibiotics","resistance","overuse","surgery","research"], notes:"antibiotics = big success | bacteria resist faster than new drugs | survivors multiply | overuse (viral illness) | risk: unsafe surgery | solutions: finish course, careful prescribing, fund research",
 model:"The lecture warns that bacteria are developing resistance to antibiotics faster than new drugs appear, mainly because of overuse. This could make common surgery dangerous. Authorities recommend that patients finish their courses, doctors prescribe carefully, and governments support research into alternatives. This situation is a serious threat to public health.",
 ar:"البكتيريا تطور مقاومة للمضادات الحيوية أسرع من ظهور أدوية جديدة بسبب الإفراط في استخدامها، مما قد يجعل الجراحة خطرة، ويُنصح بإكمال العلاج والوصف الحذر وتمويل البحث."},
{id:"rl18", title:"Ancient trade routes", transcript:"The Silk Road was not a single road but a network of routes connecting China with the Mediterranean. Merchants rarely travelled the whole distance; goods passed through many hands along the way. Silk, spices, and precious metals moved west, while glass, horses, and wool moved east. Equally important was the exchange of ideas. Religions, technologies such as papermaking, and even diseases travelled with the caravans. Cities along the routes became wealthy and cosmopolitan, and their cultures blended influences from many regions.",
 keywords:["Silk Road","network","merchants","ideas","cities"], notes:"Silk Road = network not 1 road | goods relayed | west: silk, spice | east: glass, horses | ideas, religion, paper, disease | trade cities rich + mixed culture",
 model:"The speaker explains that the Silk Road was a network of routes where goods were passed between many merchants. Silk and spices went west, and glass and horses went east. Ideas, religions, technologies, and diseases also spread, making cities along the routes wealthy and culturally mixed.",
 ar:"طريق الحرير شبكة طرق تنتقل عبرها البضائع بين تجار كثيرين، وانتقلت معها الأفكار والأديان والتقنيات والأمراض، فازدهرت المدن على الطريق وتمازجت ثقافاتها."},
{id:"rl19", title:"Procrastination", transcript:"Procrastination is often blamed on poor time management, but researchers describe it as a problem of emotion. People delay tasks that make them feel anxious, bored, or uncertain, because avoiding the task gives immediate relief. Unfortunately, the relief is short-lived and is followed by guilt and stress. Strategies that work focus on reducing the emotional barrier. Breaking a project into small steps, starting with just five minutes, and forgiving oneself for past delays have all been shown to help. Self-criticism, in contrast, tends to make the habit worse.",
 keywords:["procrastination","emotion","relief","small steps","self-compassion"], notes:"not time mgmt – emotion | avoid anxiety/boredom -> quick relief | then guilt | fixes: small steps, 5 min start, self-forgiveness | self-criticism worsens",
 model:"The lecture argues that procrastination is an emotional problem rather than poor time management, since people avoid unpleasant tasks for short-term relief and then feel guilty. Useful strategies include dividing work into small steps and forgiving oneself, whereas harsh self-criticism makes the habit worse. Overall, kindness to oneself seems to be more effective.",
 ar:"التسويف مشكلة عاطفية لا إدارة وقت؛ نتجنب المهام المزعجة لراحة مؤقتة يتبعها شعور بالذنب، والحل بتقسيم العمل لخطوات صغيرة وتسامح الذات لا جلدها."},
{id:"rl20", title:"Smart cities", transcript:"A smart city uses sensors and data to manage services more efficiently. For example, traffic lights can respond to real-time congestion, and rubbish bins can signal when they are full. Such systems may reduce costs and pollution. However, collecting large amounts of information about residents raises privacy concerns. Who owns the data, and how long is it stored? Urban researchers argue that technology alone is not enough. Successful smart cities involve citizens in decisions and ensure that digital services are accessible to everyone, including older people and those with low incomes.",
 keywords:["sensors","data","efficiency","privacy","citizens"], notes:"smart city = sensors + data | e.g. traffic lights, bins | saves cost/pollution | privacy: who owns data? | need citizen input + access for all",
 model:"The lecture describes smart cities that use sensors and data, for instance in traffic lights and rubbish bins, to cut costs and pollution. It raises concerns about privacy and data ownership, and concludes that success requires public participation and services that everyone can access. Overall, technology must serve every resident.",
 ar:"المدن الذكية تستخدم الحساسات والبيانات لتحسين الخدمات وخفض التكلفة والتلوث، لكنها تثير مخاوف الخصوصية، ونجاحها يتطلب إشراك المواطنين وإتاحة الخدمات للجميع."},
{id:"rl21", title:"The science of habits", transcript:"Habits are behaviours we perform automatically, and they account for a large portion of our daily routine. According to research, every habit follows a loop of three parts: a cue, a routine, and a reward. For example, feeling stressed may cue a snack, which provides comfort. To change a habit, it is usually easier to keep the cue and the reward but replace the routine. Someone who snacks when stressed might take a short walk instead. Consistency is crucial, since new habits take weeks, not days, to become automatic.",
 keywords:["habit loop","cue","routine","reward","consistency"], notes:"habit = auto behaviour | loop: cue -> routine -> reward | change: keep cue + reward, swap routine | e.g. walk not snack | takes weeks",
 model:"The speaker explains that habits follow a loop of cue, routine, and reward. The easiest way to change one is to keep the cue and the reward but substitute a new routine, such as walking instead of snacking. New habits need consistent repetition over several weeks to become automatic.",
 ar:"العادات تتبع حلقة من محفز وسلوك ومكافأة، ولتغييرها نبقي المحفز والمكافأة ونستبدل السلوك، وتحتاج العادة الجديدة أسابيع من الانتظام."},
{id:"rl22", title:"Desalination", transcript:"In dry regions, desalination, the removal of salt from seawater, is becoming a vital source of fresh water. The most common method today is reverse osmosis, in which seawater is forced through a membrane that blocks salt. Although the technology works well, it consumes large amounts of energy and produces a concentrated brine that must be disposed of carefully, or it can harm marine life. Engineers are therefore developing more efficient membranes and plants powered by solar energy. If these efforts succeed, desalination could supply water to millions without heavy environmental costs.",
 keywords:["desalination","reverse osmosis","energy","brine","solar"], notes:"desal = remove salt | reverse osmosis: membrane | problems: energy hungry, brine harms sea life | fixes: better membranes, solar plants | goal: cheap, green water",
 model:"The lecture covers desalination, mainly reverse osmosis, which pushes seawater through a membrane to remove salt. It uses a lot of energy and creates harmful brine, so engineers are working on efficient membranes and solar-powered plants that could deliver water to millions with a lower environmental cost.",
 ar:"تحلية المياه تزيل الملح عبر التناضح العكسي لكنها تستهلك طاقة كبيرة وتنتج محلولًا ملحيًا يضر الحياة البحرية، ويعمل المهندسون على أغشية أكفأ ومحطات تعمل بالطاقة الشمسية."},
{id:"rl23", title:"Early childhood education", transcript:"Economists and educators agree that investment in early childhood is among the most effective forms of public spending. Children's brains develop rapidly before the age of five, and positive experiences during this period support later success in school. Long-term studies have followed children who attended high-quality preschool programmes. As adults, they were more likely to graduate, find stable employment, and avoid crime. Because such programmes cost money, some critics hesitate. Yet the savings in later social costs generally exceed the initial expense, making early education a sound investment.",
 keywords:["early childhood","brain development","preschool","long-term","investment"], notes:"early years = best spending | brain grows fast <5 | studies: preschool kids graduate more, work, less crime | cost vs savings -> savings win",
 model:"The lecture argues that early childhood education is one of the best public investments because the brain develops quickly before age five. Long-term studies show that preschool attendees graduate more often, find stable jobs, and commit less crime, and the later savings usually outweigh the initial cost.",
 ar:"التعليم المبكر من أفضل الاستثمارات العامة لأن الدماغ ينمو بسرعة قبل الخامسة، وأظهرت الدراسات أن خريجي رياض الأطفال الجيدة ينجحون ويعملون أكثر، والتوفير لاحقًا يفوق التكلفة."},
{id:"rl24", title:"Migration of birds", transcript:"Every year, billions of birds travel thousands of kilometres between breeding and wintering areas. How do they find their way? Research suggests that birds use several cues at once. They follow the position of the sun by day and the pattern of stars by night. They also appear to sense the Earth's magnetic field, and some use landmarks such as coastlines and mountains. Young birds that migrate for the first time often travel alone, relying on inherited instinct. Unfortunately, light pollution and habitat loss now disrupt many migration routes.",
 keywords:["migration","sun and stars","magnetic field","instinct","light pollution"], notes:"billions travel far | navigate: sun, stars, magnetic field, landmarks | first-timers alone = instinct | threats: light pollution, habitat loss",
 model:"The speaker explains that migratory birds navigate by combining the sun, the stars, the Earth's magnetic field, and landmarks, while young birds rely on inherited instinct. Sadly, light pollution and the loss of habitats are interfering with many of their traditional routes. Protecting these routes is therefore an urgent conservation task.",
 ar:"الطيور المهاجرة تهتدي بالشمس والنجوم والمجال المغناطيسي والمعالم، والصغار تعتمد على الغريزة، لكن التلوث الضوئي وفقدان الموائل يعطلان مساراتها."}
];
